 public class Object{public string name;public bool destroyed;public static GameObject Instantiate(GameObject x,Transform p,bool w)=>x.Clone(p);public static void Destroy(Object x){if(x==null)return;x.destroyed=true;if(x is GameObject g){g.SetActive(false);GameObject.Notify(g.transform.parent?.gameObject,"OnTransformChildrenChanged");g.transform.parent?.Children.Remove(g.transform);foreach(var c in g.Components.ToArray())c.GetType().GetMethod("OnDestroy",BindingFlags.Instance|BindingFlags.NonPublic)?.Invoke(c,null);foreach(var t in g.transform.Children.ToArray())Destroy(t.gameObject);}}}
