 public class GameObject:Object{public static readonly List<GameObject> All=new List<GameObject>();public readonly List<Component> Components=new List<Component>();public Transform transform;public bool activeSelf=true;public bool activeInHierarchy=>activeSelf&&(transform.parent==null||transform.parent.gameObject.activeInHierarchy);public GameObject(string n=""){All.Add(this);name=n;transform=AddComponent<Transform>();transform.name=n;}public void SetActive(bool a){activeSelf=a;}public T AddComponent<T>()where T:Component,new(){var c=new T{gameObject=this};Components.Add(c);return c;}public T[] GetComponentsInChildren<T>(bool inactive)where T:Component=>Components.OfType<T>().Concat(transform.Children.SelectMany(t=>t.gameObject.GetComponentsInChildren<T>(inactive))).ToArray();public static void Notify(GameObject go,string name){if(go==null)return;foreach(var c in go.Components.ToArray())c.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance)?.Invoke(c,null);}
 public GameObject Clone(Transform p){var g=new GameObject(name);g.transform.SetParent(p);g.transform.localPosition=transform.localPosition;g.transform.localScale=transform.localScale;g.transform.localRotation=transform.localRotation;g.activeSelf=activeSelf;foreach(var c in Components){if(c is Renderer r){var v=g.AddComponent<Renderer>();v.enabled=r.enabled;v.sharedMaterial=r.sharedMaterial;}if(c is MeshFilter m)g.AddComponent<MeshFilter>().sharedMesh=m.sharedMesh;if(c is Animator a){var v=g.AddComponent<Animator>();v.enabled=a.enabled;v.applyRootMotion=a.applyRootMotion;}if(c is Animation a2){var v=g.AddComponent<Animation>();v.enabled=a2.enabled;v.playAutomatically=a2.playAutomatically;}}foreach(var t in transform.Children)t.gameObject.Clone(g.transform);return g;}}
